using Microsoft.Dynamics365.LocalizationFramework;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERFormatDestinationSettingsFormEventHandler</c> manages the settings form behaviour for new ER destination for 'MET Azure Storage'
/// </summary>
public class METERFormatDestinationSettingsFormEventHandler
{
}

Method.Source:
    /// <summary>
    /// post handler form init
    /// </summary>
    /// <param name = "args">XppPrePostArgs</param>
    [PostHandlerFor(formStr(ERFormatDestinationSettings), formMethodStr(ERFormatDestinationSettings, init))]
    public static void ERFormatDestinationSettings_Post_init(XppPrePostArgs args)
    {
        FormRun formRun = args.getThis();
        ERIFormatFileDestinationSettingsStorage settingsStorage = args.getThis();
        var settings = METERFormatDestinationSettingsFormEventHandler::getSaveInAzureStorageSettings(settingsStorage);

        FormStringControl azureStorageTypeControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageType));
        azureStorageTypeControl.text(settings.parmDocuTypeId());

        FormCheckBoxControl enabledControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageEnable));
        enabledControl.checked(settings.isEnabled());

        FormCheckBoxControl encryptedControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageEncrypted));
        encryptedControl.checked(settings.parmIsEncrypted());
    }

    /// <summary>
    /// pre handler form closeOk
    /// </summary>
    /// <param name = "args">XppPrePostArgs</param>
    [PreHandlerFor(formStr(ERFormatDestinationSettings), formMethodStr(ERFormatDestinationSettings, closeOk))]
    public static void ERFormatDestinationSettings_Pre_closeOk(XppPrePostArgs args)
    {
        FormRun formRun = args.getThis();
        ERIFormatFileDestinationSettingsStorage settingsStorage = args.getThis();
        var settings = METERFormatDestinationSettingsFormEventHandler::getSaveInAzureStorageSettings(settingsStorage);

        FormStringControl azureStorageTypeControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageType));
        settings.parmDocuTypeId(azureStorageTypeControl.text());

        FormCheckBoxControl enabledControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageEnable));
        settings.setEnabled(enabledControl.checked());

        FormCheckBoxControl encryptedControl = formRun.design().controlName(formControlStr(ERFormatDestinationSettings, METAzureStorageEncrypted));
        settings.parmIsEncrypted(encryptedControl.checked());
    }

/// <summary>
/// Lookup method to show only 'MET Azure storage' document types
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ERFormatDestinationSettings, METAzureStorageType), FormControlEventType::Lookup),
SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void METAzureStorageType_OnLookup(FormControl sender, FormControlEventArgs e)
{
    var query = new Query();
    QueryBuildDataSource dataSource = query.addDataSource(tableNum(DocuType));
    dataSource.fields().addField(fieldNum(DocuType, TypeId));
    dataSource.addRange(fieldNum(DocuType, TypeGroup)).value(queryValue(DocuTypeGroup::File));
    dataSource.addRange(fieldNum(DocuType, FilePlace)).value(queryValue(DocuFilePlace::METAzureStorage));
                    
    var lookup = SysTableLookup::newParameters(tableNum(DocuType), sender);
    lookup.parmQuery(query);
    lookup.addLookupfield(fieldNum(DocuType, TypeId));
    lookup.performFormLookup();
}

private static METERFormatDestinationAzureStorageSettings getSaveInAzureStorageSettings(ERIFormatFileDestinationSettingsStorage _settingsStorage)
{
    METERFormatDestinationAzureStorageSettings ret = _settingsStorage.getSettingsByKey(METERFormatDestinationAzureStorageSettings::SettingsKey);
    if (ret == null)
    {
        ret = new METERFormatDestinationAzureStorageSettings();
        _settingsStorage.addSettings(ret);
    }
    return ret;
}
